      cidade = cidadeEstado[0] || null;
      estado = cidadeEstado[1] || null;
    }

    return {
      rua: rua || null,
      numero: numeroLimpo,
      bairro: bairro || null,
      cidade: cidade || null,
      estado: estado || null,
      cep: cep || null,
    };
  }

